import pathlib,sys
src=pathlib.Path(sys.argv[1]).read_text();assert ' pristine=e.save_state()' in src
prefix=src.split(' pristine=e.save_state()')[0];sys.argv=[sys.argv[0],sys.argv[2],sys.argv[3]]
tail=" # Function timings: Timer2 is used only if disabled; every call restores core state.\n snap=e.save_state()\n def cost(name,args):\n  state=e.save_state();tm=0x04000108\n  assert not(e.u16(tm+2)&128),'Timer2 already active'\n  assert S+200<=0x02040000\n  vals={'cb':sy['gMain']+4,'prev':e.callback2(),'tm':tm,**{'a'+str(i):v for i,v in enumerate(list(args)+[0]*(6-len(args)))},'ret':0,'fn':sy[name]|1,'res':S+192,'ticks':S+196}\n  o=[0xb510,0xb082,('l',4,'cb'),('l',0,'prev'),0x6020,('l',4,'tm'),0x2000,0x8060,0x8020,0x2081,0x8060,('l',0,'a0'),('l',1,'a1'),('l',2,'a2'),('l',3,'a3'),('l',4,'a4'),0x9400,('l',4,'a5'),0x9401,('l',4,'ret'),0x46a6,('l',4,'fn'),0x4720]\n  vals['ret']=(S+len(o)*2)|1\n  o += [('l',4,'res'),0x6020,('l',4,'tm'),0x8821,0x2000,0x8060,('l',4,'ticks'),0x6021,0xb002,0xbd10]\n  if len(o)&1:o.append(0x46c0)\n  off=len(o)*2;keys=list(vals)\n  for i,q in enumerate(o):\n   if isinstance(q,tuple):\n    disp=S+off+4*keys.index(q[2])-((S+i*2+4)&~3)\n    assert disp%4==0 and 0<=disp<=1020\n    o[i]=0x4800+(q[1]<<8)+disp//4\n  code=struct.pack('<'+'H'*len(o),*o)+struct.pack('<'+'I'*len(vals),*vals.values())\n  assert len(code)<=192\n  try:\n   e.write(S,code);e.write(S+192,struct.pack('<II',0xdecafbad,0xdecafbad));w(sy['gMain']+4,S|1)\n   for _ in range(20):\n    e.run(1)\n    if e.u32(S+196)!=0xdecafbad:break\n   else:raise AssertionError(('timed call timeout',name))\n   ticks=e.u32(S+196);assert 0<ticks<65000,(name,ticks)\n   return ticks\n  finally:e.load_state(state)\n try:\n  for n in range(1,387):\n   call('GetSetPokedexFlag',n,2);call('GetSetPokedexFlag',n,3)\n  region(0);call('CB2_OpenPokedexFromStartMenu');wait('Task_PokedexScreen',6)\n  e.press('A');wait('Task_DexScreen_NumericalOrder',6);e.hold('DOWN');e.run(80);e.hold();e.run(20)\n  p=dex();tid=e.u8(p+65);lm=sy['gTasks']+tid*40+8;win=e.u8(lm+16);row=e.u16(lm+26);first=e.u16(lm+24);maxshow=e.u16(lm+14)\n  iy=maxshow-1;idx=first+iy;lp=e.u32(lm);item=e.u32(lp+idx*8+4);label=e.u32(lp+idx*8);y=iy*14+(e.u8(lm+20)&15)\n  font=e.u8(lm+23)&63;pad=(e.u8(lm+22)>>3)&7\n  assert call('GetFontAttribute',font,1)+pad==14\n  wd=e.u8(sy['gWindows']+win*12+3)*8\n  cases=[('ListMenuDummyTask',(0,)),('ScrollWindow',(win,0,14,0)),('ListMenuPrint',(lm,label,e.u8(lm+18),y)),('DexScreen_PrintMonDexNo',(win,0,item&65535,12,y)),('BlitMenuInfoIcon',(win,0,40,y)),('BlitMenuInfoIcon_type',(win,1,120,y)),('FillWindowPixelRect',(win,0,0,0,wd,2)),('ListMenuPrintEntries',(lm,idx,iy,1)),('ListMenuErasePrintedCursor',(lm,row)),('ListMenuDrawCursor',(lm,)),('CopyWindowToVram',(win,2)),('ListMenuScroll',(lm,1,1)),('ListMenuChangeSelection',(lm,1,1,1))]\n  sy['BlitMenuInfoIcon_type']=sy['BlitMenuInfoIcon']\n  for phase in range(3):\n   measurements={name:cost(name,args) for name,args in cases}\n   overhead=measurements['ListMenuDummyTask']\n   emit('native_function_cycles',dict(phase=phase,timer_divisor=64,baseline_ticks=overhead,cycles={n:max(0,t-overhead)*64 for n,t in measurements.items()},scope='isolated calls; includes interrupts; nested calls not additive'))\n   e.run(1)\n finally:e.load_state(snap)\nafter=saves();after[str(sav)]=h(sav.read_bytes());assert after==old\nemit('original_saves_preserved',True)\n"
exec(compile(prefix+tail,'native-profile','exec'))
